import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../auth/AuthContext';

export default function Navbar() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  return (
    <nav style={{
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      padding: '16px 40px',
      background: 'linear-gradient(135deg, #0F172A 0%, #1E3A8A 100%)', // กรมท่าเข้มไล่เฉดน้ำเงินตัดกับพื้นหลัง
      boxShadow: '0 4px 20px rgba(15, 23, 42, 0.15)',
      position: 'sticky',
      top: 0,
      zIndex: 100
    }}>
      {/* Brand Logo */}
      <div style={{ fontSize: '20px', fontWeight: '800', letterSpacing: '-0.5px' }}>
        <Link to="/" style={{ color: '#FFFFFF', textDecoration: 'none', display: 'flex', alignItems: 'center', gap: '10px' }}>
          <span style={{
            background: 'rgba(255, 255, 255, 0.1)',
            padding: '6px 10px',
            borderRadius: '10px',
            fontSize: '18px',
            backdropFilter: 'blur(4px)'
          }}>🎓</span>
          <span>Uni<span style={{ color: '#60A5FA' }}>Equipment</span></span>
        </Link>
      </div>

      {/* Navigation Links */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '24px' }}>
        <Link to="/" style={{ color: '#E2E8F0', textDecoration: 'none', fontWeight: '500', fontSize: '14px', transition: 'color 0.2s' }}>
          หน้าแรก
        </Link>

        {user.role === 'member' && (
          <Link to="/my-borrowings" style={{ color: '#E2E8F0', textDecoration: 'none', fontWeight: '500', fontSize: '14px' }}>
            ประวัติการยืม
          </Link>
        )}

        {user.role === 'admin' && (
          <Link to="/admin" style={{ 
            color: '#F59E0B', 
            background: 'rgba(245, 158, 11, 0.15)',
            padding: '6px 12px',
            borderRadius: '8px',
            textDecoration: 'none', 
            fontWeight: '600', 
            fontSize: '13px' 
          }}>
            🛡️ จัดการหลังบ้าน
          </Link>
        )}

        {/* User Status / Auth Buttons */}
        {user.role === 'guest' ? (
          <div style={{ display: 'flex', gap: '12px', alignItems: 'center' }}>
            <Link to="/login" style={{
              color: '#F8FAFC',
              padding: '8px 18px',
              borderRadius: '8px',
              textDecoration: 'none',
              fontWeight: '600',
              fontSize: '14px',
              border: '1px solid rgba(255, 255, 255, 0.2)',
              background: 'rgba(255, 255, 255, 0.05)'
            }}>
              เข้าสู่ระบบ
            </Link>
            <Link to="/register" style={{
              background: '#3B82F6',
              color: '#FFFFFF',
              padding: '8px 18px',
              borderRadius: '8px',
              textDecoration: 'none',
              fontWeight: '600',
              fontSize: '14px',
              boxShadow: '0 2px 10px rgba(59, 130, 246, 0.4)'
            }}>
              สมัครสมาชิก
            </Link>
          </div>
        ) : (
          <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
            <span style={{ fontSize: '14px', color: '#CBD5E1' }}>
              👤 {user.name} (<strong style={{ color: '#60A5FA' }}>{user.role}</strong>)
            </span>
            <button 
              onClick={() => { logout(); navigate('/'); }}
              style={{
                background: 'rgba(239, 68, 68, 0.2)',
                color: '#FCA5A5',
                border: '1px solid rgba(239, 68, 68, 0.3)',
                padding: '6px 14px',
                borderRadius: '8px',
                cursor: 'pointer',
                fontWeight: '600',
                fontSize: '13px'
              }}
            >
              ออกจากระบบ
            </button>
          </div>
        )}
      </div>
    </nav>
  );
}
